import CoreText
import Foundation

/// The gallery's contents, generated by scripts/build-catalog.py.
struct Catalog: Decodable {
    let sampleText: String
    let casks: [Cask]

    /// Loads Catalog.json and registers the preview fonts the gallery renders it with.
    static let bundled: Catalog = {
        guard let url = Bundle.main.url(forResource: "Catalog", withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let catalog = try? JSONDecoder().decode(Catalog.self, from: data) else {
            fatalError("Catalog.json is missing or malformed; run scripts/build-catalog.py")
        }
        let previews = catalog.casks.compactMap { Bundle.main.url(forResource: $0.previewFile, withExtension: nil) }
        CTFontManagerRegisterFontURLs(previews as CFArray, .process, true, nil)
        return catalog
    }()
}

/// A Homebrew font cask. Its token doubles as the On-Demand Resources tag holding its fonts.
struct Cask: Decodable, Identifiable, Hashable {
    let token: String
    let name: String
    let homepage: URL
    let installs: Int
    let bytes: Int64
    /// How many fonts the cask holds, whether or not this build ships them.
    let fonts: Int
    /// Asset catalog names of the cask's font files, empty when `--fonts` left them out of this build.
    let assets: [String]
    /// PostScript name of the face previewed in the gallery, used to check whether the cask is installed.
    let primaryFont: String
    /// How the primary face is drawn, which the sidebar filters on.
    let style: DesignStyle
    let previewFile: String

    var id: String { token }
    var previewFontName: String { (previewFile as NSString).deletingPathExtension }
    /// Whether this build carries the cask's fonts. Only a bundled cask has an On-Demand Resources tag
    /// to download, so only a bundled cask can be installed.
    var isBundled: Bool { !assets.isEmpty }
    var license: String? {
        guard let url = Bundle.main.url(forResource: token, withExtension: "txt") else { return nil }
        return try? String(contentsOf: url, encoding: .utf8)
    }
}
